import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { addToCart } from '../services/api';
import { isAuthenticated } from '../util/auth';

const ProductCard = ({ product, onCartUpdate, index = 0 }) => {
  const [loading, setLoading] = useState(false);
  const [quantity, setQuantity] = useState(1);
  const [isHovered, setIsHovered] = useState(false);
  const handleAddToCart = async () => {
    if (!isAuthenticated()) {
      alert('Please login to add items to cart');
      return;
    }

    try {
      setLoading(true);
      await addToCart(product._id, quantity);
      if (onCartUpdate) {
        onCartUpdate();
      }
      alert('Product added to cart!');
    } catch (error) {
      alert(error.response?.data?.message || 'Error adding to cart');
    } finally {
      setLoading(false);
    }
  };

  const getCategoryClass = (category) => {
    const classes = {
      milk: 'bg-blue-100 text-blue-800',
      ghee: 'bg-amber-100 text-amber-800',
      cheese: 'bg-yellow-100 text-yellow-800',
      butter: 'bg-orange-100 text-orange-800',
      curd: 'bg-green-100 text-green-800',
      paneer: 'bg-purple-100 text-purple-800',
      cream: 'bg-pink-100 text-pink-800',
      yogurt: 'bg-teal-100 text-teal-800',
      lassi: 'bg-cyan-100 text-cyan-800',
      buttermilk: 'bg-lime-100 text-lime-800'
    };
    return classes[category] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="card">
      {/* Product Image */}
      <div className="h-48 bg-gray-100 flex items-center justify-center overflow-hidden">
        {product.image ? (
          <img 
            src={product.image} 
            alt={product.name}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-24 h-24 bg-primary-200 rounded-full flex items-center justify-center">
            <span className="text-4xl">🥛</span>
          </div>
        )}
      </div>

      {/* Product Info */}
      <div className="p-4">
        {/* Category Badge */}
        <span className={`inline-block px-2 py-1 text-xs font-medium rounded-full mb-2 ${getCategoryClass(product.category)}`}>
          {product.category}
        </span>

        {/* Product Name */}
        <h3 className="text-lg font-semibold text-gray-800 mb-1">
          {product.name}
        </h3>

        {/* Description */}
        <p className="text-sm text-gray-600 mb-2 line-clamp-2">
          {product.description}
        </p>

        {/* Price and Unit */}
        <div className="flex items-center justify-between mb-3">
          <div>
            <span className="text-xl font-bold text-primary-600">₹{product.price}</span>
            <span className="text-sm text-gray-500">/{product.unit}</span>
          </div>
          <div className="text-sm text-gray-500">
            Stock: {product.stock}
          </div>
        </div>

        {/* Quantity Selector and Add to Cart */}
        <div className="flex items-center space-x-2">
          <div className="flex items-center border border-gray-300 rounded-lg">
            <button
              onClick={() => setQuantity(Math.max(1, quantity - 1))}
              className="w-8 h-8 flex items-center justify-center text-gray-600 hover:bg-gray-100"
            >
              -
            </button>
            <span className="w-8 text-center">{quantity}</span>
            <button
              onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}
              className="w-8 h-8 flex items-center justify-center text-gray-600 hover:bg-gray-100"
            >
              +
            </button>
          </div>
          <button
            onClick={handleAddToCart}
            disabled={loading || product.stock === 0}
            className="flex-1 btn btn-primary disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? 'Adding...' : product.stock === 0 ? 'Out of Stock' : 'Add to Cart'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductCard;
